421	  const validTiers = new Set(tierOrder);
422	  const colors = getTierColors();
423	  const groups = {};
424	  tierOrder.forEach(t => { groups[t] = []; });
425	
426	  // 兜底组：收集无法解析梯度的英雄（避免污染 T4）
427	  const unknownGroup = [];
428	
429	  heroes.forEach(h => {
430	    const tierField = gameConfig.hasLanes ? getTierField(h) : "tier";
431	    const tier = h[tierField];
432	    if (tier && validTiers.has(tier)) {
433	      groups[tier].push(h);
434	    } else {
435	      // 诊断：捕获异常梯度值
436	      console.warn("[梯度异常] 英雄:", h.name,
437	        "| 分路:", h.lane || "-",
438	        "| 梯度字段:", tierField,
439	        "| 梯度值:", tier,
440	        "| 有效字段存在:", {
441	          tier_zscore: "tier_zscore" in h ? h.tier_zscore : "缺失",
442	          tier_simple: "tier_simple" in h ? h.tier_simple : "缺失",
443	          tier: "tier" in h ? h.tier : "缺失"
444	        });
445	      unknownGroup.push(h);
446	    }
447	  });
448	
449	  // 组内按分数排序
